import { toIndexEntry, type ContentSite } from "./types";

/**
 * The text of `src/content-index.generated.ts`: the client-safe list of pages
 * (section, slug, path, title, h1, description) the home page and /docs read
 * for their links. No bodies, no sources. Deterministic: same pages, same text.
 */
export function renderIndexModule(site: ContentSite): string {
  const entries: string = JSON.stringify(site.pages.map(toIndexEntry), null, 2);
  return [
    "// Generated by apps/web/scripts/content-index.mjs (the web build's prebuild step)",
    "// from apps/web/content/**/*.md before every build, typecheck, test run and dev",
    "// server. Not committed (git-ignored); do not edit. A production build lists",
    "// live pages only, a preview build (SHOW_DRAFTS=1) lists drafts too.",
    "// Only what the home page and /docs need for their links. The page bodies",
    "// are rendered at build time and never reach the client bundle.",
    'import type { ContentIndexEntry } from "./content/constants";',
    "",
    `export const CONTENT_INDEX: ReadonlyArray<ContentIndexEntry> = ${entries};`,
    "",
  ].join("\n");
}
